Q: Add Autoplay to this JS Slider A: <p>This will enable autoplay but also allow you to jump indexes and continue autoplay from that whatever index you're on</p>

<pre><code>const autoplay = () =&gt; {
  const max = $controls.length;

  setInterval(() =&gt; {
    // use the internal activeIndex to track
    $controls.eq(activeIndex).next().click();

    if(activeIndex + 1 === max){
       $controls.eq(0).click();
    }
  }, 3000); 
}

const init = () =&gt; {
    assignEls()
    prepareDom()
    attachListeners()
    autoplay()
}
</code></pre>

